/**
 * Record a calibration for one step, in force from `valid_from` onwards.
 *
 * History is kept: readings are processed with the calibration in force
 * when they were taken, so recalibrating a sensor never rewrites the
 * past. Every required calibration parameter of the step's algorithm
 * must be given. Rolled back if the stream tier cannot be notified.
 *
 * Args:
 *     step_key: Step being calibrated.
 *     params: Calibration parameters of the step's algorithm.
 *     valid_from: Time at which this calibration takes effect. Defaults to now.
 */
export const devicesPostprocessingsCalibrationsCreate = async (deviceUuid: string,
    postprocessingId: string,
    stepCalibrationRequest: StepCalibrationRequest, options?: Parameters<typeof apiFetch>[1]): Promise<StepCalibration> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<StepCalibration>(getDevicesPostprocessingsCalibrationsCreateUrl(deviceUuid,postprocessingId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(stepCalibrationRequest),
    schema: StepCalibration
  }
);}





